<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;
class UpdateAgreementTemplateRequest extends FormRequest {public function authorize():bool{return $this->user()?->hasPermission('agreement-templates.edit')??false;}protected function prepareForValidation():void{$this->merge(['is_default'=>$this->boolean('is_default'),'is_active'=>$this->boolean('is_active')]);}public function rules():array{return ['name'=>['required','string','max:255'],'title'=>['required','string','max:255'],'intro_text'=>['nullable','string','max:5000'],'terms_content'=>['required','string','max:100000'],'is_default'=>['boolean'],'is_active'=>['boolean']];}}
